def new_side(hunks_text):
    # hunks_text holds only the hunks of one file; the
    # ---/+++ file header lines were already removed.
    n, out = 0, []
    for line in hunks_text.splitlines():
        if line.startswith("@@ "):
            n = int(line.split()[1][1:].split(",")[0])
        elif line.startswith("+") or line.startswith(" "):
            out.append((n, line[1:]))
            n += 1
    return out

fn cut_at_line(head: &str) -> &str {
    match head.rfind('\n') {
        Some(i) if i > 0 => &head[..=i],
        _ => head,
    }
}

fn main() {
    let out = cut_at_line("\nabcdef");
    println!("{:?}", out);
}
